$fields=['Price'=>fn($r)=>$r['id']?trim($r['price'].' '.$r['price_unit']):'No response','Packaging'=>fn($r)=>(string)($r['packaging']??''),'Container / Net Weight'=>fn($r)=>(string)($r['container_weight']??''),'Freight Method'=>fn($r)=>(string)($r['freight_method']??''),'FOB Location'=>fn($r)=>(string)($r['fob_location']??''),'Freight / Surcharges'=>fn($r)=>(string)($r['freight_surcharges']??''),'Minimum Order'=>fn($r)=>(string)($r['minimum_order']??''),'Lead Time'=>fn($r)=>(string)($r['lead_time']??''),'Availability'=>fn($r)=>(string)($r['availability']??''),'Payment Terms'=>fn($r)=>(string)($r['payment_terms']??''),'Country of Origin'=>fn($r)=>(string)($r['country_of_origin']??''),'Manufacturer'=>fn($r)=>(string)($r['manufacturer']??''),'Quote Expiration'=>fn($r)=>(string)($r['quote_expiration']??''),'Notes'=>fn($r)=>(string)($r['notes']??'')];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quote Comparison | <?= sourcing_h($rfq['rfq_number']) ?></title><style>body{margin:0;background:#f4f7fa;font:14px Arial;color:#17212b}.top{background:#0c2340;color:#fff;padding:18px}.wrap,.topin{max-width:1400px;margin:auto}.wrap{padding:22px}h1{color:#0c2340}.scroll{overflow:auto;background:#fff;border:1px solid #d9e0e6;border-radius:12px}table{border-collapse:collapse;width:100%;min-width:900px}th,td{border-bottom:1px solid #e5eaee;border-right:1px solid #e5eaee;padding:11px;vertical-align:top;text-align:left}th{background:#f8fafc;color:#0c2340;position:sticky;top:0}td:first-child,th:first-child{font-weight:700;background:#fbfcfd;min-width:180px;position:sticky;left:0;z-index:1}.btn{display:inline-block;text-decoration:none;background:#0c2340;color:#fff;padding:9px 12px;border-radius:8px;font-weight:700}.toolbar{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap}@media(max-width:700px){.wrap{padding:12px}}</style></head><body><div class="top"><div class="topin"><strong>Lowe Chemical Company | Internal Sourcing</strong></div></div><main class="wrap"><div class="toolbar"><div><h1>Supplier Quote Comparison</h1><div><b><?= sourcing_h($rfq['rfq_number']) ?></b> · <?= sourcing_h($rfq['product_name']) ?> · <?= sourcing_h((string)$rfq['quantity'].' '.(string)$rfq['quantity_uom']) ?></div></div><div><?=workflow_back_link('btn')?> <a class="btn" href="rfq-responses.php?id=<?= (int)$id ?>">Responses</a> <a class="btn" href="rfq-list.php">RFQ List</a></div></div><div class="scroll"><table><thead><tr><th>Quote Detail</th><?php foreach($rows as $r):?><th><?= sourcing_h($r['supplier_name']) ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($fields as $label=>$fn):?><tr><td><?= sourcing_h($label) ?></td><?php foreach($rows as $r):?><td><?= nl2br(sourcing_h($fn($r))) ?></td><?php endforeach;?></tr><?php endfor